def _call_ollama(prompt: str, model: str = OLLAMA_MODEL) -> str | None:
    """Call local Ollama API with streaming. Returns response text or None on failure.

    Uses streaming mode to avoid idle-socket timeouts on slow CPU inference.
    Each streamed chunk resets the socket timer.
    """
    payload = json.dumps({
        "model": model,
        "prompt": prompt,
        "stream": True,
        "options": {
            "num_predict": MAX_TOKENS,
            "temperature": 0.7,
        },
    }).encode()

    req = Request(
        OLLAMA_URL,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        chunks: list[str] = []
        start = time.time()
        with urlopen(req, timeout=OLLAMA_TIMEOUT) as resp:
            while True:
                line = resp.readline()
